function normalizeRecord(json) {
  if (!json) return null;

  if (Array.isArray(json.records)) {
    return json.records.map(normalizeRecord).filter(Boolean);
  }

  if (json.fields) {
    return {
      id: json.id || json.recordId,
      fields: json.fields,
    };
  }

  const { id, recordId, createdTime, ...rest } = json;

  return {
    id: id || recordId,
    fields: rest,
  };
}

function getRecords(nodeName) {
  const items = $items(nodeName) || [];
  const records = [];

  for (const item of items) {
    const normalized = normalizeRecord(item.json);

    if (Array.isArray(normalized)) {
      records.push(...normalized);
    } else if (normalized) {
      records.push(normalized);
    }
  }

  return records.filter((record) => record.id);
}

function asLinks(value) {
  if (!value) return [];

  if (Array.isArray(value)) {
    return value
      .map((item) => {
        if (typeof item === "string") return item;
        if (item?.id) return item.id;
        if (item?.recordId) return item.recordId;
        return String(item || "");
      })
      .map((item) => item.trim())
      .filter(Boolean);
  }

  if (typeof value === "string") {
    return [value.trim()].filter(Boolean);
  }

  return [];
}

function getString(value) {
  return String(value || "").trim();
}

function normalize(value) {
  return getString(value)
    .toLowerCase()
    .replaceAll("ı", "i")
    .replaceAll("ğ", "g")
    .replaceAll("ü", "u")
    .replaceAll("ş", "s")
    .replaceAll("ö", "o")
    .replaceAll("ç", "c")
    .trim();
}

function formatDate(dateText) {
  if (!dateText) return "-";

  return new Date(dateText).toLocaleDateString("tr-TR", {
    day: "2-digit",
    month: "long",
    year: "numeric",
  });
}

function isPresent(attendance) {
  const status = normalize(attendance.fields.Durum);

  return (
    status === "geldi" ||
    status === "gec geldi" ||
    status === "geç geldi"
  );
}

function buildEmailHtml({
  studentName,
  sessionName,
  dateText,
  lessonHour,
  trackingCode,
}) {
  return `
<div style="font-family:Arial,Helvetica,sans-serif;background:#f1f5f9;padding:32px;">
  <div style="max-width:640px;margin:auto;background:white;border-radius:24px;overflow:hidden;border:1px solid #e2e8f0;">
    <div style="background:#7f1d1d;color:white;padding:28px 32px;">
      <div style="font-size:12px;letter-spacing:4px;text-transform:uppercase;color:#fecaca;font-weight:700;">
        AkıllıSınıf AI
      </div>
      <h1 style="margin:12px 0 0;font-size:28px;line-height:1.2;color:#ffffff;">
        Yoklama Katılım Uyarısı
      </h1>
      <p style="margin:12px 0 0;color:#fee2e2;font-size:15px;line-height:1.6;">
        Bu bildirim n8n otomasyonu tarafından otomatik oluşturulmuştur.
      </p>
    </div>

    <div style="padding:32px;color:#0f172a;">
      <p style="margin:0 0 16px;font-size:16px;line-height:1.7;">
        Merhaba <strong>${studentName}</strong>,
      </p>

      <p style="margin:0 0 20px;font-size:16px;line-height:1.7;">
        Aşağıdaki yoklama oturumu için sistemde katılım kaydınız bulunamadı.
      </p>

      <div style="margin:22px 0;padding:18px;border-radius:18px;background:#f8fafc;border:1px solid #e2e8f0;">
        <p style="margin:0;color:#64748b;font-size:12px;text-transform:uppercase;font-weight:700;letter-spacing:1px;">
          Yoklama Oturumu
        </p>
        <p style="margin:8px 0 0;font-size:20px;font-weight:700;color:#0f172a;">
          ${sessionName}
        </p>
      </div>

      <div style="margin:22px 0;padding:18px;border-radius:18px;background:#fef2f2;border:1px solid #fecaca;">
        <p style="margin:0;color:#b91c1c;font-size:12px;text-transform:uppercase;font-weight:700;letter-spacing:1px;">
          Tarih ve Ders Saati
        </p>
        <p style="margin:8px 0 0;font-size:20px;font-weight:700;color:#7f1d1d;">
          ${dateText} · ${lessonHour}. ders
        </p>
      </div>

      <p style="margin:22px 0;font-size:15px;line-height:1.7;color:#475569;">
        Eğer derse katıldığınızı düşünüyorsanız lütfen öğretmeninizle iletişime geçin.
        Aksi halde bu kayıt devamsızlık olarak değerlendirilebilir.
      </p>

      <div style="margin-top:28px;padding:16px;border-radius:16px;background:#f8fafc;border:1px solid #e2e8f0;color:#64748b;font-size:12px;line-height:1.6;">
        Sistem takip kodu: ${trackingCode}
      </div>
    </div>

    <div style="background:#f8fafc;padding:20px 32px;border-top:1px solid #e2e8f0;color:#64748b;font-size:12px;line-height:1.6;">
      AkıllıSınıf AI · Yapay Zekâ Destekli Sınıf Performans ve Erken Uyarı Sistemi
    </div>
  </div>
</div>
`;
}

const students = getRecords("GET Students");
const memberships = getRecords("GET Active Memberships");
const sessions = getRecords("GET Recent Attendance Sessions");
const attendanceRecords = getRecords("GET Attendance Records");
const existingNotifications = getRecords("GET Existing Attendance Notifications");

const output = [];

for (const session of sessions) {
  const sessionId = session.id;
  const sessionName = getString(session.fields.Oturum_Adi) || "Yoklama Oturumu";
  const sessionDate = getString(session.fields.Tarih);
  const lessonHour = getString(session.fields.Ders_Saati) || "1";
  const classIds = asLinks(session.fields.Sinif);

  if (!sessionDate || classIds.length === 0) continue;

  const classId = classIds[0];

  const classMemberships = memberships.filter((membership) => {
    const membershipClassIds = asLinks(membership.fields.Sinif);
    return membershipClassIds.includes(classId);
  });

  for (const membership of classMemberships) {
    const studentId = asLinks(membership.fields.Kullanici)[0];

    if (!studentId) continue;

    const student = students.find((item) => item.id === studentId);
    const studentName = getString(student?.fields?.Ad_Soyad) || "Öğrenci";
    const studentEmail = getString(student?.fields?.Eposta);

    if (!studentEmail) continue;

    const hasPresentRecord = attendanceRecords.some((attendance) => {
      const attendanceStudentIds = asLinks(attendance.fields.Ogrenci);
      const attendanceClassIds = asLinks(attendance.fields.Sinif);
      const attendanceDate = getString(attendance.fields.Tarih);
      const attendanceLessonHour = getString(attendance.fields.Ders_Saati);

      return (
        attendanceStudentIds.includes(studentId) &&
        attendanceClassIds.includes(classId) &&
        attendanceDate === sessionDate &&
        attendanceLessonHour === lessonHour &&
        isPresent(attendance)
      );
    });

    if (hasPresentRecord) continue;

    const trackingCode = `YOKLAMA:${sessionId}:ALICI:${studentId}`;

    const duplicateExists = existingNotifications.some((notification) => {
      const message = getString(notification.fields.Mesaj);
      return message.includes(trackingCode);
    });

    if (duplicateExists) continue;

    const dateText = formatDate(sessionDate);

    const message =
      `Merhaba ${studentName}, "${sessionName}" yoklama oturumu için katılım kaydınız bulunamadı. ` +
      `Tarih: ${dateText}, ders saati: ${lessonHour}. ` +
      `Eğer derse katıldığınızı düşünüyorsanız öğretmeninizle iletişime geçin.\n\n` +
      `Sistem takip kodu: ${trackingCode}`;

    const emailSubject = `Yoklama katılım uyarısı: ${dateText}`;

    const emailHtml = buildEmailHtml({
      studentName,
      sessionName,
      dateText,
      lessonHour,
      trackingCode,
    });

    output.push({
      json: {
        emailTo: studentEmail,
        emailSubject,
        emailHtml,
        studentName,
        sessionName,
        dateText,
        lessonHour,
        trackingCode,
        fields: {
          Bildirim_Basligi: "Devamsızlık uyarısı",
          Alici: [studentId],
          Sinif: [classId],
          Bildirim_Turu: "Devamsızlık Uyarısı",
          Mesaj: message,
          Onem_Derecesi: "Yüksek",
          Okundu_Mu: false,
          Gonderildi_Mi: true,
          Kanal: "E-posta + Webhook",
        },
      },
    });
  }
}

return output;
